def merge(intervals):
    """Return merged, sorted, disjoint copies of [start, end] intervals.

    Intervals that overlap or merely touch are combined. The input is not
    modified.
    """
    if not intervals:
        return []

    ordered = sorted((list(interval) for interval in intervals), key=lambda x: (x[0], x[1]))
    merged = [ordered[0]]

    for start, end in ordered[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            if end > last_end:
                merged[-1][1] = end
        else:
            merged.append([start, end])

    return merged
